-- 1. Create tables
CREATE TABLE category (
  id bigint GENERATED BY DEFAULT AS IDENTITY,
  is_parent boolean NOT NULL,
  level int NOT NULL,
  name varchar(50) NOT NULL,
  parent_category_id bigint DEFAULT NULL,
  PRIMARY KEY (id),
  CONSTRAINT UK_46ccwnsi9409t36lurvtyljak UNIQUE (name)
);

CREATE TABLE product (
  id bigint GENERATED BY DEFAULT AS IDENTITY,
  average_rating double precision NOT NULL DEFAULT '0',
  battery_capacity varchar(255) DEFAULT NULL,
  battery_type varchar(255) DEFAULT NULL,
  brand varchar(50) DEFAULT NULL,
  color varchar(255) DEFAULT NULL,
  connection_port varchar(255) DEFAULT NULL,
  created_at timestamp(6) DEFAULT NULL,
  description text,
  detailed_review text,
  dimension varchar(255) DEFAULT NULL,
  discount_persent int DEFAULT NULL,
  discounted_price int DEFAULT NULL,
  num_ratings int NOT NULL DEFAULT '0',
  powerful_performance text,
  price int NOT NULL,
  quantity_sold bigint DEFAULT NULL,
  ram_capacity varchar(255) DEFAULT NULL,
  rom_capacity varchar(255) DEFAULT NULL,
  screen_size varchar(255) DEFAULT NULL,
  seller_id bigint DEFAULT NULL,
  title varchar(100) DEFAULT NULL,
  weight varchar(255) DEFAULT NULL,
  category_id bigint DEFAULT NULL,
  PRIMARY KEY (id)
);

CREATE TABLE image (
  id bigint GENERATED BY DEFAULT AS IDENTITY,
  download_url varchar(500) DEFAULT NULL,
  file_name varchar(255) DEFAULT NULL,
  file_type varchar(50) DEFAULT NULL,
  product bigint DEFAULT NULL,
  PRIMARY KEY (id)
);

CREATE TABLE sizes (
  id bigint GENERATED BY DEFAULT AS IDENTITY,
  name varchar(255) DEFAULT NULL,
  quantity int NOT NULL,
  product_id bigint NOT NULL,
  PRIMARY KEY (id)
);

CREATE TABLE review (
  id bigint GENERATED BY DEFAULT AS IDENTITY,
  review_content varchar(500) DEFAULT NULL,
  created_at timestamp(6) DEFAULT NULL,
  rating int NOT NULL,
  product_id bigint NOT NULL,
  user_id bigint NOT NULL,
  user_first_name varchar(255) DEFAULT NULL,
  user_last_name varchar(255) DEFAULT NULL,
  PRIMARY KEY (id)
);

-- 2. Add foreign keys
ALTER TABLE category ADD CONSTRAINT FK_category_parent FOREIGN KEY (parent_category_id) REFERENCES category(id);
ALTER TABLE product ADD CONSTRAINT FK_product_category FOREIGN KEY (category_id) REFERENCES category(id);
ALTER TABLE image ADD CONSTRAINT FK_image_product FOREIGN KEY (product) REFERENCES product(id);
ALTER TABLE sizes ADD CONSTRAINT FK_sizes_product FOREIGN KEY (product_id) REFERENCES product(id);
ALTER TABLE review ADD CONSTRAINT FK_review_product FOREIGN KEY (product_id) REFERENCES product(id);

