SELECT setval(pg_get_serial_sequence('product', 'id'), coalesce(max(id), 1)) FROM product;
SELECT setval(pg_get_serial_sequence('image', 'id'), coalesce(max(id), 1)) FROM image;
SELECT setval(pg_get_serial_sequence('sizes', 'id'), coalesce(max(id), 1)) FROM sizes;
SELECT setval(pg_get_serial_sequence('review', 'id'), coalesce(max(id), 1)) FROM review;
